function [def,y] = NormedIFFT(x,l);% l : longueur du domaine de definition en frequencen = length(x);y = ifft(rshift(fftshift(x)))*l/2/pi;y = fftshift(y);def = 2*pi/l * (-n/2 : n/2-1);% Written by Maureen Clerc and Jerome Kalifa, 1997% clerc@cmapx.polytechnique.fr, kalifa@cmapx.polytechnique.fr        %   % Part of WaveLab Version 802% Built Sunday, October 3, 1999 8:52:27 AM% This is Copyrighted Material% For Copying permissions see COPYING.m% Comments? e-mail wavelab@stat.stanford.edu%       